/* C API of the Rust port of `comfort.c`, generated by rust-anything. */
#ifndef COMFORT_RS_H
#define COMFORT_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double CalcFangerPPD(double PMV);
double CalcRelativeAirVelocity(double AirVel, double ActMet);
double CalcSatVapPressFromTemp(double Temp);
double CalcSatVapPressFromTempTorr(double Temp);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_CalcFangerPPD(double PMV);
double rust_anything_CalcRelativeAirVelocity(double AirVel, double ActMet);
double rust_anything_CalcSatVapPressFromTemp(double Temp);
double rust_anything_CalcSatVapPressFromTempTorr(double Temp);

#endif /* COMFORT_RS_H */
